CREATE TABLE IF NOT EXISTS cinema_showings (  id INTEGER PRIMARY KEY AUTOINCREMENT,  movie_title TEXT NOT NULL,  showing_date TEXT NOT NULL,  showing_time TEXT NOT NULL,  screen TEXT,  price REAL DEFAULT 0,  total_seats INTEGER DEFAULT 100,  booked_seats INTEGER DEFAULT 0,  rating TEXT,  duration_minutes INTEGER,  genre TEXT,  status TEXT DEFAULT 'scheduled',  created_at TEXT DEFAULT (datetime('now')));
